-- ShasthoCare complete development seed data
-- Run AFTER database/schema.sql. Development/demo use only.
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;
START TRANSACTION;

ON DUPLICATE KEY UPDATE first_name=VALUES(first_name),last_name=VALUES(last_name),phone=VALUES(phone),password_hash=VALUES(password_hash),is_verified=1,is_active=1;
ON DUPLICATE KEY UPDATE label=VALUES(label);
ON DUPLICATE KEY UPDATE description=VALUES(description),is_active=1;

ON DUPLICATE KEY UPDATE name=VALUES(name),icon=VALUES(icon),description=VALUES(description),sort_order=VALUES(sort_order),is_featured=1,is_active=1;
ON DUPLICATE KEY UPDATE name=VALUES(name),description=VALUES(description),is_active=1;
ON DUPLICATE KEY UPDATE name=VALUES(name),description=VALUES(description),is_active=1;

ON DUPLICATE KEY UPDATE name=VALUES(name),generic_name=VALUES(generic_name),brand_id=VALUES(brand_id),manufacturer_id=VALUES(manufacturer_id),category_id=VALUES(category_id),product_type=VALUES(product_type),dosage_form=VALUES(dosage_form),strength=VALUES(strength),pack_size=VALUES(pack_size),unit_label=VALUES(unit_label),unit_price=VALUES(unit_price),units_per_strip=VALUES(units_per_strip),strip_price=VALUES(strip_price),strips_per_box=VALUES(strips_per_box),units_per_box=VALUES(units_per_box),box_price=VALUES(box_price),discount_percent=VALUES(discount_percent),short_description=VALUES(short_description),description=VALUES(description),ingredients=VALUES(ingredients),usage_info=VALUES(usage_info),warnings=VALUES(warnings),storage_info=VALUES(storage_info),regular_price=VALUES(regular_price),sale_price=VALUES(sale_price),cost_price=VALUES(cost_price),prescription_required=VALUES(prescription_required),is_featured=VALUES(is_featured),is_best_seller=VALUES(is_best_seller),is_new_arrival=VALUES(is_new_arrival),is_active=1,seo_title=VALUES(seo_title),seo_description=VALUES(seo_description);

ON DUPLICATE KEY UPDATE description=VALUES(description),icon=VALUES(icon),price=VALUES(price),sort_order=VALUES(sort_order),is_active=1;
ON DUPLICATE KEY UPDATE title=VALUES(title),subtitle=VALUES(subtitle),content=VALUES(content),button_text=VALUES(button_text),button_url=VALUES(button_url),position=VALUES(position),sort_order=VALUES(sort_order),is_active=1;
ON DUPLICATE KEY UPDATE title=VALUES(title),is_enabled=VALUES(is_enabled),sort_order=VALUES(sort_order);
ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);
ON DUPLICATE KEY UPDATE title=VALUES(title),content=VALUES(content),seo_title=VALUES(seo_title),seo_description=VALUES(seo_description),is_active=1;
ON DUPLICATE KEY UPDATE label=VALUES(label),url=VALUES(url),location=VALUES(location),sort_order=VALUES(sort_order),is_active=1;
ON DUPLICATE KEY UPDATE subtotal=VALUES(subtotal),discount=VALUES(discount),shipping_fee=VALUES(shipping_fee),total=VALUES(total),payment_method=VALUES(payment_method),payment_sender_last4=VALUES(payment_sender_last4),payment_transaction_id=VALUES(payment_transaction_id),payment_status=VALUES(payment_status),status=VALUES(status),tracking_code=VALUES(tracking_code),courier_name=VALUES(courier_name);
ON DUPLICATE KEY UPDATE product_name=VALUES(product_name),unit_price=VALUES(unit_price),price_type=VALUES(price_type),units_per_pack=VALUES(units_per_pack),total_units=VALUES(total_units),discount=VALUES(discount),quantity=VALUES(quantity),subtotal=VALUES(subtotal);
ON DUPLICATE KEY UPDATE transaction_ref=VALUES(transaction_ref),amount=VALUES(amount),status=VALUES(status),payload_json=VALUES(payload_json);
COMMIT;
SET FOREIGN_KEY_CHECKS=1;

-- NOTE: server/src/scripts/seed.js additionally generates local demo SVG product/prescription images.
-- The SQL seed is intentionally file-system independent; storefront gracefully uses placeholders until images are uploaded/generated.
-- Link supplied catalog images only by exact product name, only when no image exists.
