INSERT INTO products(id,name,slug,sku,generic_name,brand_id,manufacturer_id,category_id,product_type,dosage_form,strength,pack_size,unit_label,unit_price,units_per_strip,strip_price,strips_per_box,units_per_box,box_price,discount_percent,short_description,description,ingredients,usage_info,warnings,storage_info,regular_price,sale_price,cost_price,tax_rate,prescription_required,is_featured,is_best_seller,is_new_arrival,is_active,low_stock_threshold,rating_avg,review_count,seo_title,seo_description) VALUES
(1,'Paracetamol 500 mg Tablet','paracetamol-500-mg-tablet','DEMO0001','Paracetamol',1,1,1,'Medicine','Tablet','500 mg','10 tablets','Tablet',3.6,10,36.0,10,100,342.0,20,'<p>A common analgesic and antipyretic product listing used in this demo pharmacy catalog.</p>','<p>A common analgesic and antipyretic product listing used in this demo pharmacy catalog.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Paracetamol 500 mg per tablet.</p>','<p>Use only according to the package label or advice from a qualified healthcare professional.</p>','<p>Do not exceed the labeled amount. Check other medicines for paracetamol/acetaminophen to avoid accidental duplication. Seek professional advice if you have liver disease or symptoms persist.</p>','<p>Store below 30°C in a dry place, protected from direct light and out of reach of children.</p>',45,36.0,24,0,0,1,1,0,1,10,4.2,18,'Paracetamol 500 mg Tablet | ShasthoCare','Paracetamol 500 mg Tablet demo product listing with brand, pack, pricing and safety information.'),(2,'Oral Rehydration Salts Sachet','oral-rehydration-salts-sachet','DEMO0002','Oral rehydration salts',2,2,1,'Medicine','Powder for oral solution','WHO-style electrolyte blend','10 sachets','Tablet',11.2,10,112.0,10,100,1064.0,20,'<p>Electrolyte replacement product intended for preparation according to the pack instructions.</p>','<p>Electrolyte replacement product intended for preparation according to the pack instructions.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Glucose and balanced electrolytes in a dry powder sachet.</p>','<p>Prepare exactly with the amount of safe drinking water stated on the product label. Follow professional guidance for children or persistent illness.</p>','<p>Discard prepared solution according to the label. Seek medical care for severe dehydration, persistent vomiting, blood in stool, or concerning symptoms.</p>','<p>Keep sachets sealed in a cool, dry place away from moisture.</p>',140,112.0,76,0,0,1,1,0,1,10,4.3,19,'Oral Rehydration Salts Sachet | ShasthoCare','Oral Rehydration Salts Sachet demo product listing with brand, pack, pricing and safety information.'),(3,'Antacid Chewable Tablet','antacid-chewable-tablet','DEMO0003','Calcium carbonate blend',3,3,1,'Medicine','Chewable tablet','Demo strength','20 tablets','Tablet',9.2,10,92.0,10,100,874.0,20,'<p>Demo non-prescription antacid catalog item for short-term relief labeling.</p>','<p>Demo non-prescription antacid catalog item for short-term relief labeling.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Calcium carbonate-based antacid blend.</p>','<p>Follow the package directions. Separate from other medicines when advised because antacids can affect absorption.</p>','<p>Frequent or persistent symptoms should be assessed by a healthcare professional. Review suitability in kidney disease or during pregnancy with a professional.</p>','<p>Store in a dry place below 30°C with the container tightly closed.</p>',115,92.0,63,0,0,1,1,0,1,10,4.4,20,'Antacid Chewable Tablet | ShasthoCare','Antacid Chewable Tablet demo product listing with brand, pack, pricing and safety information.'),(4,'Allergy Relief Tablet 10 mg','allergy-relief-tablet-10-mg','DEMO0004','Cetirizine hydrochloride',4,4,1,'Medicine','Tablet','10 mg','10 tablets','Tablet',5.2,10,52.0,10,100,494.0,20,'<p>Antihistamine product listing for allergy-related symptoms; demo catalog information only.</p>','<p>Antihistamine product listing for allergy-related symptoms; demo catalog information only.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Cetirizine hydrochloride 10 mg per tablet.</p>','<p>Use according to the product label or clinician advice.</p>','<p>May cause drowsiness in some people. Avoid activities requiring alertness until you know how it affects you. Ask a professional about use with other sedating medicines.</p>','<p>Store below 30°C, protected from moisture and light.</p>',65,52.0,35,0,0,1,1,0,1,10,4.5,21,'Allergy Relief Tablet 10 mg | ShasthoCare','Allergy Relief Tablet 10 mg demo product listing with brand, pack, pricing and safety information.'),(5,'Prescription Antibiotic Demo 500 mg','prescription-antibiotic-demo-500-mg','DEMO0005','Demo antibiotic ingredient',5,5,1,'Prescription Medicine','Capsule','500 mg','14 capsules','Tablet',37.6,10,376.0,10,100,3572.0,20,'<p>A fictional prescription-only product included solely to demonstrate prescription approval and checkout controls.</p>','<p>A fictional prescription-only product included solely to demonstrate prescription approval and checkout controls.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Fictional demonstration antibiotic ingredient, 500 mg.</p>','<p>Prescription required. Use only when prescribed and follow the prescriber and dispensing label exactly.</p>','<p>Do not self-start, share, or reuse antibiotics. This is fictional demo data and must not be used for treatment decisions.</p>','<p>Store as directed by the dispensing label, away from children.</p>',470,376.0,256,0,1,1,1,0,1,10,4.6,22,'Prescription Antibiotic Demo 500 mg | ShasthoCare','Prescription Antibiotic Demo 500 mg demo product listing with brand, pack, pricing and safety information.'),(6,'Vitamin C 1000 mg Effervescent','vitamin-c-1000-mg-effervescent','DEMO0006','Ascorbic acid',6,1,2,'Supplement','Effervescent tablet','1000 mg','20 tablets','Tablet',34.96,10,349.6,10,100,3321.2,20,'<p>Vitamin C supplement in effervescent form.</p>','<p>Vitamin C supplement in effervescent form.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Ascorbic acid with effervescent base.</p>','<p>Use according to the supplement label and dietary needs advised by a qualified professional.</p>','<p>Supplements do not replace a balanced diet. Ask a clinician about high-dose use if you have kidney problems or take regular medicines.</p>','<p>Keep tube tightly closed in a cool, dry place away from moisture.</p>',437,349.6,238,0,0,1,1,0,1,10,4.7,23,'Vitamin C 1000 mg Effervescent | ShasthoCare','Vitamin C 1000 mg Effervescent demo product listing with brand, pack, pricing and safety information.'),(7,'Vitamin D3 2000 IU Softgel','vitamin-d3-2000-iu-softgel','DEMO0007','Cholecalciferol',7,2,2,'Supplement','Softgel','2000 IU','30 softgels','Tablet',28.64,10,286.4,10,100,2720.8,20,'<p>Vitamin D3 dietary supplement product listing.</p>','<p>Vitamin D3 dietary supplement product listing.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Cholecalciferol (vitamin D3).</p>','<p>Use only as directed on the label or by a healthcare professional, especially if combining with other vitamin D products.</p>','<p>Avoid excessive vitamin D intake. People with high calcium levels, kidney disease, or related conditions should seek professional guidance.</p>','<p>Store in a cool, dry place away from direct sunlight.</p>',358,286.4,195,0,0,1,1,0,1,10,4.8,24,'Vitamin D3 2000 IU Softgel | ShasthoCare','Vitamin D3 2000 IU Softgel demo product listing with brand, pack, pricing and safety information.'),(8,'Calcium + Vitamin D3 Tablet','calcium-vitamin-d3-tablet','DEMO0008','Calcium carbonate + cholecalciferol',8,3,2,'Supplement','Tablet','Calcium/D3 blend','30 tablets','Tablet',25.12,10,251.2,10,100,2386.4,20,'<p>Combined calcium and vitamin D supplement for general nutritional support.</p>','<p>Combined calcium and vitamin D supplement for general nutritional support.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Calcium carbonate with vitamin D3.</p>','<p>Take according to the product label or professional recommendation.</p>','<p>Calcium can interact with some medicines. Seek advice if you use thyroid medicine, certain antibiotics, or have kidney stones or kidney disease.</p>','<p>Keep in a cool, dry place with lid closed.</p>',314,251.2,171,0,0,1,1,0,1,10,4.2,25,'Calcium + Vitamin D3 Tablet | ShasthoCare','Calcium + Vitamin D3 Tablet demo product listing with brand, pack, pricing and safety information.'),(9,'Omega-3 Fish Oil 1000 mg','omega-3-fish-oil-1000-mg','DEMO0009','Fish oil concentrate',9,4,2,'Supplement','Softgel','1000 mg','60 softgels','Tablet',64.48,10,644.8,10,100,6125.6,20,'<p>Omega-3 nutritional supplement for general dietary support.</p>','<p>Omega-3 nutritional supplement for general dietary support.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Fish oil concentrate containing omega-3 fatty acids.</p>','<p>Use according to the label with food if recommended by the manufacturer.</p>','<p>Ask a healthcare professional before use if you take blood-thinning medicines, have a bleeding disorder, or have a fish allergy.</p>','<p>Store tightly closed away from heat and direct light.</p>',806,644.8,438,0,0,1,1,0,1,10,4.3,26,'Omega-3 Fish Oil 1000 mg | ShasthoCare','Omega-3 Fish Oil 1000 mg demo product listing with brand, pack, pricing and safety information.'),(10,'Zinc 20 mg Tablet','zinc-20-mg-tablet','DEMO0010','Zinc',10,5,2,'Supplement','Tablet','20 mg','30 tablets','Tablet',18.8,10,188.0,10,100,1786.0,20,'<p>Zinc nutritional supplement product listing.</p>','<p>Zinc nutritional supplement product listing.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Zinc salt providing 20 mg elemental zinc per labeled serving.</p>','<p>Follow the supplement label. Long-term high-dose use should be discussed with a professional.</p>','<p>Excess zinc may cause adverse effects and can affect copper status or interact with some medicines.</p>','<p>Store below 30°C in a dry place.</p>',235,188.0,128,0,0,1,1,0,1,10,4.4,27,'Zinc 20 mg Tablet | ShasthoCare','Zinc 20 mg Tablet demo product listing with brand, pack, pricing and safety information.'),(11,'Daily Multivitamin','daily-multivitamin','DEMO0011','Multivitamin and mineral blend',1,1,2,'Supplement','Tablet','Multi-nutrient','30 tablets','Tablet',43.04,10,430.4,10,100,4088.8,20,'<p>General multivitamin supplement for adults.</p>','<p>General multivitamin supplement for adults.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Blend of common vitamins and minerals as listed on the package.</p>','<p>Use according to the nutrition label and avoid unnecessarily combining with duplicate supplements.</p>','<p>Not a substitute for a balanced diet. Discuss with a professional if pregnant, breastfeeding, or using long-term medicines.</p>','<p>Keep sealed in a cool, dry place.</p>',538,430.4,293,0,0,1,0,0,1,10,4.5,28,'Daily Multivitamin | ShasthoCare','Daily Multivitamin demo product listing with brand, pack, pricing and safety information.'),(12,'Gentle Skin Cleanser 250 ml','gentle-skin-cleanser-250-ml','DEMO0012','Non-soap cleansing base',2,2,3,'Personal Care','Liquid cleanser','Fragrance-light formula','250 ml bottle','Tablet',41.2,10,412.0,10,100,3914.0,20,'<p>Gentle daily cleanser for face and body.</p>','<p>Gentle daily cleanser for face and body.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Mild surfactant and moisturizing cleansing base.</p>','<p>Use externally as directed on the product label and rinse well.</p>','<p>For external use only. Stop use if persistent irritation occurs and avoid direct eye contact.</p>','<p>Store at room temperature with cap closed.</p>',515,412.0,280,0,0,1,0,0,1,10,4.6,29,'Gentle Skin Cleanser 250 ml | ShasthoCare','Gentle Skin Cleanser 250 ml demo product listing with brand, pack, pricing and safety information.'),(13,'Alcohol Hand Sanitizer 200 ml','alcohol-hand-sanitizer-200-ml','DEMO0013','Alcohol hand rub',3,3,3,'Personal Care','Gel','70% alcohol demo label','200 ml bottle','Tablet',14.4,10,144.0,10,100,1368.0,20,'<p>Portable hand hygiene product for use when soap and water are not readily available.</p>','<p>Portable hand hygiene product for use when soap and water are not readily available.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Alcohol-based hand cleansing gel with humectants.</p>','<p>Apply according to label instructions and allow hands to dry completely.</p>','<p>Flammable. Keep away from flame, heat, eyes, and children. For external use only.</p>','<p>Keep tightly closed away from heat and ignition sources.</p>',180,144.0,98,0,0,0,0,0,1,10,4.7,30,'Alcohol Hand Sanitizer 200 ml | ShasthoCare','Alcohol Hand Sanitizer 200 ml demo product listing with brand, pack, pricing and safety information.'),(14,'Sensitive Toothpaste 100 g','sensitive-toothpaste-100-g','DEMO0014','Desensitizing toothpaste',4,4,3,'Personal Care','Paste','Daily use formula','100 g tube','Tablet',17.44,10,174.4,10,100,1656.8,20,'<p>Toothpaste formulated for sensitive teeth and routine oral hygiene.</p>','<p>Toothpaste formulated for sensitive teeth and routine oral hygiene.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Tooth-cleaning base with a desensitizing active ingredient as labeled.</p>','<p>Brush according to dental guidance and package directions.</p>','<p>Do not swallow. Persistent tooth sensitivity or pain should be evaluated by a dental professional.</p>','<p>Keep capped at room temperature.</p>',218,174.4,119,0,0,0,0,0,1,10,4.8,31,'Sensitive Toothpaste 100 g | ShasthoCare','Sensitive Toothpaste 100 g demo product listing with brand, pack, pricing and safety information.'),(15,'Mild Body Wash 300 ml','mild-body-wash-300-ml','DEMO0015','Gentle body cleansing base',5,5,3,'Personal Care','Liquid','Mild formula','300 ml bottle','Tablet',27.76,10,277.6,10,100,2637.2,20,'<p>Daily body wash for gentle cleansing.</p>','<p>Daily body wash for gentle cleansing.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Mild cleansing agents and skin-conditioning ingredients.</p>','<p>Apply externally and rinse thoroughly.</p>','<p>Avoid eye contact. Discontinue if irritation persists.</p>','<p>Store at room temperature away from direct sunlight.</p>',347,277.6,189,0,0,0,0,0,1,10,4.2,32,'Mild Body Wash 300 ml | ShasthoCare','Mild Body Wash 300 ml demo product listing with brand, pack, pricing and safety information.'),(16,'Baby Moisturizing Lotion 200 ml','baby-moisturizing-lotion-200-ml','DEMO0016','Baby emollient lotion',6,1,4,'Baby Care','Lotion','Gentle formula','200 ml bottle','Tablet',32.24,10,322.4,10,100,3062.8,20,'<p>Gentle moisturizer designed for baby skin care.</p>','<p>Gentle moisturizer designed for baby skin care.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Emollient and moisturizing base formulated for delicate skin.</p>','<p>Apply externally as directed. Patch test when using a new skin product if advised.</p>','<p>Avoid broken skin and eyes. Stop use if irritation or rash develops and seek advice if needed.</p>','<p>Keep closed at room temperature and away from direct heat.</p>',403,322.4,219,0,0,0,0,0,1,10,4.3,33,'Baby Moisturizing Lotion 200 ml | ShasthoCare','Baby Moisturizing Lotion 200 ml demo product listing with brand, pack, pricing and safety information.'),(17,'Baby Shampoo 200 ml','baby-shampoo-200-ml','DEMO0017','Mild baby shampoo base',7,2,4,'Baby Care','Liquid shampoo','Tear-minimized formula','200 ml bottle','Tablet',26.0,10,260.0,10,100,2470.0,20,'<p>Gentle shampoo for routine baby hair cleansing.</p>','<p>Gentle shampoo for routine baby hair cleansing.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Mild cleansing surfactants formulated for baby hair.</p>','<p>Use a small amount externally and rinse thoroughly according to the label.</p>','<p>Adult supervision required. Avoid direct eye contact despite gentle formulation.</p>','<p>Store upright with cap closed.</p>',325,260.0,177,0,0,0,0,0,1,10,4.4,34,'Baby Shampoo 200 ml | ShasthoCare','Baby Shampoo 200 ml demo product listing with brand, pack, pricing and safety information.'),(18,'Baby Diapers Medium 32 pcs','baby-diapers-medium-32-pcs','DEMO0018','Disposable absorbent diaper',8,3,4,'Baby Care','Disposable diaper','Medium','32 pieces','Tablet',69.92,10,699.2,10,100,6642.4,20,'<p>Disposable baby diapers with absorbent core and soft fit.</p>','<p>Disposable baby diapers with absorbent core and soft fit.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Absorbent core, soft inner layer, elastic side panels.</p>','<p>Change regularly and select the correct size for the child.</p>','<p>Stop use if persistent skin irritation develops. Keep packaging away from children.</p>','<p>Store clean and dry away from humidity.</p>',874,699.2,475,0,0,0,0,0,1,10,4.5,35,'Baby Diapers Medium 32 pcs | ShasthoCare','Baby Diapers Medium 32 pcs demo product listing with brand, pack, pricing and safety information.'),(19,'Digital Blood Pressure Monitor','digital-blood-pressure-monitor','DEMO0019','Automatic upper-arm BP monitor',9,4,5,'Medical Device','Device','Digital','1 device + cuff','Tablet',309.12,10,3091.2,10,100,29366.4,20,'<p>Home blood pressure monitor with automatic inflation and digital display.</p>','<p>Home blood pressure monitor with automatic inflation and digital display.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Electronic monitor, reusable upper-arm cuff and accessories.</p>','<p>Follow the device manual for cuff placement, posture, rest period, and repeated measurements. Home readings do not replace professional assessment.</p>','<p>Seek urgent care for concerning symptoms regardless of a device reading. Use the correct cuff size and keep the device calibrated as instructed.</p>','<p>Store dry, clean and protected from impact and extreme temperature.</p>',3864,3091.2,2102,0,0,0,0,0,1,10,4.6,36,'Digital Blood Pressure Monitor | ShasthoCare','Digital Blood Pressure Monitor demo product listing with brand, pack, pricing and safety information.'),(20,'Digital Glucose Meter Kit','digital-glucose-meter-kit','DEMO0020','Blood glucose monitoring system',10,5,5,'Medical Device','Device','Digital','Meter + starter accessories','Tablet',165.76,10,1657.6,10,100,15747.2,20,'<p>Home glucose meter kit for self-monitoring when directed by a healthcare professional.</p>','<p>Home glucose meter kit for self-monitoring when directed by a healthcare professional.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Electronic meter with compatible test-strip system.</p>','<p>Use only with compatible strips and follow the device manual. Treatment changes should be made only with qualified medical guidance.</p>','<p>Unexpected or very abnormal readings should be confirmed and discussed with a healthcare professional; seek urgent care for severe symptoms.</p>','<p>Keep meter and strips dry and within the temperature range stated in the manual.</p>',2072,1657.6,1127,0,0,0,0,0,1,10,4.7,37,'Digital Glucose Meter Kit | ShasthoCare','Digital Glucose Meter Kit demo product listing with brand, pack, pricing and safety information.'),(21,'Pulse Oximeter','pulse-oximeter','DEMO0021','Fingertip pulse oximeter',1,1,5,'Medical Device','Device','SpO2/PR display','1 device','Tablet',147.84,10,1478.4,10,100,14044.8,20,'<p>Portable fingertip pulse oximeter for spot measurements.</p>','<p>Portable fingertip pulse oximeter for spot measurements.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Optical fingertip sensor and digital display.</p>','<p>Use according to the manual, keeping the hand warm and still for a stable reading.</p>','<p>Readings can be affected by motion, poor circulation, nail products, skin temperature and device limitations. Symptoms matter more than a single reading.</p>','<p>Store dry and remove batteries for long storage when recommended.</p>',1848,1478.4,1005,0,0,0,0,0,1,10,4.8,38,'Pulse Oximeter | ShasthoCare','Pulse Oximeter demo product listing with brand, pack, pricing and safety information.'),(22,'Digital Thermometer','digital-thermometer','DEMO0022','Digital clinical thermometer',2,2,5,'Medical Device','Device','Digital','1 thermometer','Tablet',37.6,10,376.0,10,100,3572.0,20,'<p>Reusable digital thermometer for routine temperature measurement.</p>','<p>Reusable digital thermometer for routine temperature measurement.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Electronic temperature sensor and display.</p>','<p>Follow the manual for the selected measurement site and cleaning procedure.</p>','<p>Do not rely on temperature alone to judge illness severity. Seek professional care for concerning symptoms or high-risk patients.</p>','<p>Keep clean, dry and protected from impact.</p>',470,376.0,256,0,0,0,0,0,1,10,4.2,39,'Digital Thermometer | ShasthoCare','Digital Thermometer demo product listing with brand, pack, pricing and safety information.'),(23,'Nebulizer Machine','nebulizer-machine','DEMO0023','Compressor nebulizer',3,3,5,'Medical Device','Device','Home compressor','Machine + mask/tubing kit','Tablet',264.32,10,2643.2,10,100,25110.4,20,'<p>Home compressor nebulizer device for medications prescribed or recommended for nebulization.</p>','<p>Home compressor nebulizer device for medications prescribed or recommended for nebulization.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Compressor unit with medication cup, tubing and masks.</p>','<p>Use only with medicines or saline intended for nebulization and follow the device and prescription instructions.</p>','<p>Do not put oils or unapproved liquids in the nebulizer. Clean parts carefully to reduce contamination risk.</p>','<p>Store clean and dry with tubing and accessories protected from contamination.</p>',3304,2643.2,1797,0,0,0,0,0,1,10,4.3,40,'Nebulizer Machine | ShasthoCare','Nebulizer Machine demo product listing with brand, pack, pricing and safety information.'),(24,'First Aid Kit 24 Pieces','first-aid-kit-24-pieces','DEMO0024','Basic first aid supplies',4,4,6,'First Aid','Kit','24-piece','1 kit','Tablet',58.24,10,582.4,10,100,5532.8,20,'<p>Compact first aid kit for minor cuts, scrapes and common household needs.</p>','<p>Compact first aid kit for minor cuts, scrapes and common household needs.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Assorted plasters, gauze, tape, wipes, gloves and basic accessories.</p>','<p>Use individual components according to their labels and replace used or expired items.</p>','<p>Serious bleeding, deep wounds, burns, bites or signs of infection require medical attention.</p>','<p>Keep the case clean, dry and accessible to responsible adults.</p>',728,582.4,396,0,0,0,0,0,1,10,4.4,41,'First Aid Kit 24 Pieces | ShasthoCare','First Aid Kit 24 Pieces demo product listing with brand, pack, pricing and safety information.'),(25,'Sterile Gauze Pads 10 pcs','sterile-gauze-pads-10-pcs','DEMO0025','Sterile cotton gauze',5,5,6,'First Aid','Dressing','10 cm x 10 cm','10 sterile pads','Tablet',12.8,10,128.0,10,100,1216.0,20,'<p>Individually packed sterile gauze for wound dressing.</p>','<p>Individually packed sterile gauze for wound dressing.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Sterile woven gauze pads.</p>','<p>Use clean technique and follow first-aid or clinician guidance for wound care.</p>','<p>Do not use if the sterile pack is damaged. Seek medical attention for deep, heavily contaminated or infected wounds.</p>','<p>Keep unopened packs clean and dry.</p>',160,128.0,87,0,0,0,0,0,1,10,4.5,42,'Sterile Gauze Pads 10 pcs | ShasthoCare','Sterile Gauze Pads 10 pcs demo product listing with brand, pack, pricing and safety information.'),(26,'Elastic Crepe Bandage','elastic-crepe-bandage','DEMO0026','Elastic support bandage',6,1,6,'First Aid','Bandage','10 cm width','1 roll','Tablet',16.16,10,161.6,10,100,1535.2,20,'<p>Reusable elastic bandage for general support and first aid.</p>','<p>Reusable elastic bandage for general support and first aid.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Stretch cotton-blend support bandage.</p>','<p>Wrap with comfortable support; avoid excessive tightness.</p>','<p>Loosen immediately if there is numbness, worsening pain, discoloration or swelling below the bandage.</p>','<p>Wash and store according to the label, dry before reuse.</p>',202,161.6,110,0,0,0,0,0,1,10,4.6,43,'Elastic Crepe Bandage | ShasthoCare','Elastic Crepe Bandage demo product listing with brand, pack, pricing and safety information.'),(27,'Antiseptic Solution 100 ml','antiseptic-solution-100-ml','DEMO0027','Topical antiseptic solution',7,2,6,'First Aid','Solution','Demo topical formula','100 ml bottle','Tablet',12.0,10,120.0,10,100,1140.0,20,'<p>External antiseptic product for minor first-aid use according to the label.</p>','<p>External antiseptic product for minor first-aid use according to the label.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Topical antiseptic active ingredient in a liquid base as labeled.</p>','<p>Use externally only and follow dilution/application directions on the specific product label.</p>','<p>Avoid eyes, mouth and large/deep wounds unless professionally directed. Stop use if significant irritation occurs.</p>','<p>Keep closed, upright and away from direct heat or light.</p>',150,120.0,82,0,0,0,0,0,1,10,4.7,44,'Antiseptic Solution 100 ml | ShasthoCare','Antiseptic Solution 100 ml demo product listing with brand, pack, pricing and safety information.'),(28,'SPF 50 Broad Spectrum Sunscreen','spf-50-broad-spectrum-sunscreen','DEMO0028','Broad-spectrum sunscreen',8,3,7,'Skin Care','Cream','SPF 50','50 g tube','Tablet',55.52,10,555.2,10,100,5274.4,20,'<p>High-SPF sunscreen product for routine sun protection.</p>','<p>High-SPF sunscreen product for routine sun protection.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Broad-spectrum UV filters in a moisturizing cream base.</p>','<p>Apply according to the label before sun exposure and reapply as directed, especially after sweating or washing.</p>','<p>For external use. Sunscreen is one part of sun protection; clothing and shade are also important.</p>','<p>Store below 30°C away from direct sunlight.</p>',694,555.2,378,0,0,0,0,0,1,10,4.8,45,'SPF 50 Broad Spectrum Sunscreen | ShasthoCare','SPF 50 Broad Spectrum Sunscreen demo product listing with brand, pack, pricing and safety information.'),(29,'Moisturizing Cream 100 g','moisturizing-cream-100-g','DEMO0029','Emollient moisturizer',9,4,7,'Skin Care','Cream','Barrier-support formula','100 g jar','Tablet',38.56,10,385.6,10,100,3663.2,20,'<p>Daily moisturizer for dry or normal skin.</p>','<p>Daily moisturizer for dry or normal skin.</p><p><strong>Demo catalog note:</strong> Product information is for ecommerce demonstration and does not replace medical advice or the actual pack label.</p>','<p>Emollients, humectants and occlusive moisturizing ingredients.</p>','<p>Apply externally to clean skin as needed according to the label.</p>','<p>Avoid known allergens and discontinue if persistent irritation occurs.</p>','<p>Keep container closed at room temperature.</p>',482,385.6,262,0,0,0,0,1,1,10,4.2,46,'Moisturizing Cream 100 g | ShasthoCare','Moisturizing Cream 100 g demo product listing with brand, pack, pricing and safety information.'),(30,'Acne Care Face Wash 100 ml','acne-care-face-wash-100-ml','DEMO0030','Cleansing face wash',10,5,7,'Skin Care','Gel cleanser','Oil-control formula','100 ml tube','Tablet',31.36,10,313.6,10,100,2979.2,20,'<p>Face cleanse