(1,'Doctor Consultation','doctor-consultation','<p>Request an online consultation booking with a qualified clinician.</p>','Stethoscope',500,1,1),(2,'Lab Tests at Home','lab-tests-at-home','<p>Book a home sample collection request for available lab services.</p>','FlaskConical',350,2,1),(3,'Medicine Reminder','medicine-reminder','<p>Create a neutral reminder for medicines you already use.</p>','Bell',0,3,1),(4,'Full Body Checkup','full-body-checkup','<p>Explore configurable preventive health check packages.</p>','ClipboardCheck',2500,4,1),(5,'Pharmacist Support','pharmacist-support','<p>Ask non-diagnostic questions about orders, labels and prescription workflow.</p>','MessageCircle',0,5,1)
INSERT INTO banners(id,title,subtitle,content,button_text,button_url,position,sort_order,is_active) VALUES
(1,'Better Health, Delivered Daily.','<p>Genuine healthcare products, trusted service and convenient delivery from one modern storefront.</p>','<p><strong>Easy ordering.</strong> Secure prescription handling. Flexible delivery options.</p>','Shop Medicines','/products','hero',1,1),(2,'Prescription upload & pharmacist review','<p>Upload a prescription securely and track its review status from your account.</p>','<p>Private files are served only through authenticated endpoints.</p>','Upload Prescription','/account/prescriptions','prescription',1,1),(3,'20% Off Demo Medicines','<p>Explore pharmacy products with the default demo medicine markdown.</p>','<p>Discounts, banners and all presentation content can be changed from Admin.</p>','View Offers','/products?category=medicines','hero',2,1),(4,'Healthcare essentials for home','<p>Browse devices, nutrition, personal care and more.</p>','<p>Add a desktop and mobile image in Admin → Marketing → Banners.</p>','Browse Products','/products','hero',3,1)
