INSERT INTO cms_pages(slug,title,content,seo_title,seo_description,is_active) VALUES
('about','About ShasthoCare','<h2>Healthcare shopping made simpler</h2><p>ShasthoCare is a configurable demo pharmacy and healthcare ecommerce platform. This project demonstrates product discovery, secure accounts, prescription workflows, inventory, orders and administration.</p>','About ShasthoCare','Read About ShasthoCare for ShasthoCare.',1),('contact','Contact Us','<h2>We are here to help</h2><p>Use the contact form or the support information shown in the footer. Store contact details can be changed from Admin → Settings.</p>','Contact Us','Read Contact Us for ShasthoCare.',1),('faq','Frequently Asked Questions','<h2>Orders</h2><p>Track orders from your account or the public tracking page.</p><h2>Prescription items</h2><p>Prescription-required products need an approved prescription before fulfillment.</p>','Frequently Asked Questions','Read Frequently Asked Questions for ShasthoCare.',1),('privacy-policy','Privacy Policy','<p>This demo page can be fully edited from Admin → Content → Pages.</p>','Privacy Policy','Read Privacy Policy for ShasthoCare.',1),('terms','Terms & Conditions','<p>Demo terms. Replace with legally reviewed terms before production use.</p>','Terms & Conditions','Read Terms & Conditions for ShasthoCare.',1),('shipping-policy','Shipping Policy','<p>Shipping zones, fees and free-shipping thresholds are configurable from the admin panel.</p>','Shipping Policy','Read Shipping Policy for ShasthoCare.',1),('return-policy','Return Policy','<p>Returns are processed according to store policy and product eligibility. Replace this demo copy before production.</p>','Return Policy','Read Return Policy for ShasthoCare.',1),('refund-policy','Refund Policy','<p>Refund handling can be managed from the admin order and returns modules.</p>','Refund Policy','Read Refund Policy for ShasthoCare.',1),('medicine-disclaimer','Medicine Disclaimer','<p>Medicine information on this website is for product and catalog information only and does not replace professional medical advice, diagnosis, treatment, or the official product label.</p>','Medicine Disclaimer','Read Medicine Disclaimer for ShasthoCare.',1)
INSERT INTO shipping_zones(id,name,division,district,fee,estimated_days,free_shipping_threshold,is_active,sort_order) VALUES (1,'Inside Dhaka','Dhaka','Dhaka',80,'1-2 business days',1500,1,1),(2,'Outside Dhaka',NULL,NULL,130,'2-4 business days',2500,1,2) ON DUPLICATE KEY UPDATE fee=VALUES(fee),estimated_days=VALUES(estimated_days),is_active=1;
